/**
 * Input Validation & Normalization
 * Returns normalized input + validation errors
 */

const input = $input.first().json;
const errors = [];

// Extract and validate mode
const mode = (input.mode || "").trim().toUpperCase();
if (!mode) {
  errors.push({ stage: "input", message: "Missing required parameter: mode" });
}
if (mode !== "EXTRACT_CONTENT" && mode !== "CREATE_FILE") {
  errors.push({ stage: "input", message: `Invalid mode: ${mode}. Must be EXTRACT_CONTENT or CREATE_FILE` });
}

// Initialize output object
const output = {
  mode: mode,
  validation_errors: errors,
  timestamp: new Date().toISOString()
};

// ========== MODE: EXTRACT_CONTENT ==========
if (mode === "EXTRACT_CONTENT") {
  const url = (input.google_drive_file_url || "").trim();

  if (!url) {
    errors.push({ stage: "input", message: "Missing required parameter: google_drive_file_url" });
  } else {
    // Extract file ID from Google Drive URL
    let fileId = "";
    try {
      // Handle different Google Drive URL formats:
      // https://drive.google.com/file/d/FILE_ID/view
      // https://docs.google.com/document/d/FILE_ID/edit
      // https://docs.google.com/presentation/d/FILE_ID/edit
      // https://docs.google.com/spreadsheets/d/FILE_ID/edit

      const patterns = [
        /\/d\/([a-zA-Z0-9_-]+)/,  // /d/FILE_ID
        /id=([a-zA-Z0-9_-]+)/     // id=FILE_ID
      ];

      for (const pattern of patterns) {
        const match = url.match(pattern);
        if (match) {
          fileId = match[1];
          break;
        }
      }

      if (!fileId) {
        errors.push({ stage: "input", message: "Could not extract file ID from URL" });
      }
    } catch (e) {
      errors.push({ stage: "input", message: `URL parsing error: ${e.message}` });
    }

    output.google_drive_file_url = url;
    output.file_id = fileId;
  }
}

// ========== MODE: CREATE_FILE ==========
if (mode === "CREATE_FILE") {
  const folderId = (input.google_drive_folder_id || "").trim();
  const docType = (input.document_type || "").trim().toLowerCase();
  const templateUrl = (input.reference_template_url || "").trim();
  const inputJson = input.input_json;

  if (!folderId) {
    errors.push({ stage: "input", message: "Missing required parameter: google_drive_folder_id" });
  }

  if (!docType) {
    errors.push({ stage: "input", message: "Missing required parameter: document_type" });
  } else if (!["google_doc", "google_slides", "google_sheet"].includes(docType)) {
    errors.push({ 
      stage: "input", 
      message: `Invalid document_type: ${docType}. Must be google_doc, google_slides, or google_sheet` 
    });
  }

  if (!inputJson) {
    errors.push({ stage: "input", message: "Missing required parameter: input_json" });
  } else if (typeof inputJson !== "object") {
    errors.push({ stage: "input", message: "input_json must be a valid object" });
  }

  output.google_drive_folder_id = folderId;
  output.document_type = docType;
  output.reference_template_url = templateUrl || null;
  output.input_json = inputJson;

  // Extract template file ID if provided
  if (templateUrl) {
    try {
      const patterns = [
        /\/d\/([a-zA-Z0-9_-]+)/,
        /id=([a-zA-Z0-9_-]+)/
      ];

      let templateId = "";
      for (const pattern of patterns) {
        const match = templateUrl.match(pattern);
        if (match) {
          templateId = match[1];
          break;
        }
      }

      output.template_file_id = templateId || null;
    } catch (e) {
      errors.push({ stage: "input", message: `Template URL parsing error: ${e.message}` });
    }
  }
}

// Return with validation status
output.validation_status = errors.length === 0 ? "valid" : "invalid";
output.validation_errors = errors;

return [output];

