const extraction = $input.first().json;
const prevData = $('INP_ValidateAndRoute').first().json;
const binary = $input.first().binary;

const errors = [];
let status = "ok";
let extractedText = "";
let extractionMethod = "";

// Check if extraction failed
if (extraction.extraction_error) {
  errors.push({
    stage: "extract",
    message: extraction.error_message || "Extraction failed"
  });
  status = "error";
} else {
  // Get extracted text
  if (typeof extraction.text === "string") {
    extractedText = extraction.text;
    extractionMethod = "text";
  } else if (Array.isArray(extraction)) {
    // CSV/Excel case - convert to JSON string
    extractedText = JSON.stringify(extraction, null, 2);
    extractionMethod = "structured_data";
  } else if (typeof extraction === "object") {
    extractedText = JSON.stringify(extraction, null, 2);
    extractionMethod = "structured_data";
  }

  // Check if text is empty
  if (!extractedText || extractedText.trim().length === 0) {
    errors.push({
      stage: "extract",
      message: "Extraction succeeded but no text content found"
    });
    status = "partial";
  }
}

// Get file metadata
const mimeType = binary?.file?.mimeType || "unknown";
const fileName = binary?.file?.fileName || "unknown";

// Determine extraction method from MIME type if not set
if (!extractionMethod && mimeType) {
  if (mimeType.includes("pdf")) extractionMethod = "pdf";
  else if (mimeType.includes("text")) extractionMethod = "text";
  else if (mimeType.includes("csv")) extractionMethod = "csv";
  else if (mimeType.includes("excel") || mimeType.includes("spreadsheet")) extractionMethod = "excel";
  else if (mimeType.includes("word") || mimeType.includes("document")) extractionMethod = "doc";
  else extractionMethod = "other";
}

return [{
  status: status,
  mode: "EXTRACT_CONTENT",
  data: {
    source_url: prevData.google_drive_file_url || "",
    mimeType: mimeType,
    file_name: fileName,
    extracted_text: extractedText,
    extraction_method: extractionMethod,
    char_count: extractedText.length
  },
  errors: errors
}];

