 * Converts input_json to formatted text for Google Docs
 * Handles both template replacement and new doc generation
 */

const prevData = $('INP_ValidateAndRoute').first().json;
const inputJson = prevData.input_json || {};
const currentData = $input.first().json;

// Check if this is from template copy or new doc
const documentId = currentData.id || currentData.documentId || "";
const isTemplate = !!prevData.reference_template_url;

let content = "";
const errors = [];

try {
  if (isTemplate) {
    // STRATEGY: Template replacement
    // Replace {{placeholders}} with values from input_json
    content = "Template-based content generation:\n\n";
    for (const [key, value] of Object.entries(inputJson)) {
      if (typeof value === "string" || typeof value === "number") {
        content += `Replace {{${key}}} with: ${value}\n`;
      } else if (Array.isArray(value)) {
        content += `Replace {{${key}}} with:\n`;
        value.forEach(item => content += `• ${item}\n`);
      } else if (typeof value === "object" && value !== null) {
        content += `Replace {{${key}}} with:\n${JSON.stringify(value, null, 2)}\n`;
      }
    }
  } else {
    // STRATEGY: Generate new content from scratch
    content = generateDocumentContent(inputJson);
  }
} catch (e) {
  errors.push({
    stage: "render",
    message: `Content generation error: ${e.message}`
  });
  content = `Error generating content: ${e.message}`;
}

return [{
  document_id: documentId,
  content: content,
  input_json: inputJson,
  render_errors: errors,
  is_template: isTemplate
}];

// ========== Helper Functions ==========

function generateDocumentContent(inputJson) {
  const lines = [];

  // Add title if present
  if (inputJson.title) {
    lines.push(inputJson.title);
    lines.push("=".repeat(inputJson.title.length));
    lines.push("");
  }

  // Add metadata section if present
  if (inputJson.metadata && typeof inputJson.metadata === "object") {
    lines.push("Document Information");
    lines.push("-".repeat(20));
    for (const [key, value] of Object.entries(inputJson.metadata)) {
      lines.push(`${titleCase(key)}: ${value}`);
    }
    lines.push("");
  }

  // Process main content
  for (const [key, value] of Object.entries(inputJson)) {
    if (key === "title" || key === "metadata") continue;

    // Add section header
    lines.push("");
    lines.push(titleCase(key));
    lines.push("-".repeat(titleCase(key).length));
    lines.push("");

    // Add section content
    if (typeof value === "string") {
      lines.push(value);
    } else if (Array.isArray(value)) {
      value.forEach(item => {
        if (typeof item === "string") {
          lines.push(`• ${item}`);
        } else if (typeof item === "object") {
          lines.push(`• ${JSON.stringify(item)}`);
        }
      });
    } else if (typeof value === "object" && value !== null) {
      // Handle nested objects
      for (const [subKey, subValue] of Object.entries(value)) {
        lines.push(`${titleCase(subKey)}:`);
        if (Array.isArray(subValue)) {
          subValue.forEach(item => lines.push(`  • ${item}`));
        } else {
          lines.push(`  ${subValue}`);
        }
        lines.push("");
      }
    }
  }

  return lines.join("\n");
}

function titleCase(str) {
  return String(str)
    .replace(/_/g, " ")
    .replace(/\b\w/g, c => c.toUpperCase());
}

