/**
 * Converts input_json to tabular format for Google Sheets
 * Handles objects, arrays, and nested structures
 */

const prevData = $('INP_ValidateAndRoute').first().json;
const inputJson = prevData.input_json || {};
const currentData = $input.first().json;

const spreadsheetId = currentData.spreadsheetId || "";
const errors = [];

const rows = [];

try {
  // Check if input_json is already array of objects (table format)
  if (Array.isArray(inputJson)) {
    // Extract headers from first object
    if (inputJson.length > 0 && typeof inputJson[0] === "object") {
      const headers = Object.keys(inputJson[0]);
      rows.push(headers);

      // Add data rows
      inputJson.forEach(item => {
        const row = headers.map(h => item[h] || "");
        rows.push(row);
      });
    }
  } else if (typeof inputJson === "object") {
    // Convert object to key-value pairs
    rows.push(["Key", "Value"]);

    for (const [key, value] of Object.entries(inputJson)) {
      if (Array.isArray(value)) {
        rows.push([key, JSON.stringify(value)]);
      } else if (typeof value === "object" && value !== null) {
        rows.push([key, JSON.stringify(value, null, 2)]);
      } else {
        rows.push([key, String(value)]);
      }
    }
  }
} catch (e) {
  errors.push({
    stage: "render",
    message: `Sheet generation error: ${e.message}`
  });
}

// Convert rows to individual items for Google Sheets append
const items = rows.map((row, idx) => {
  const obj = {};
  row.forEach((cell, colIdx) => {
    obj[`col${colIdx}`] = cell;
  });
  return obj;
});

return items.length > 0 ? items : [{
  spreadsheet_id: spreadsheetId,
  error: "No data to insert",
  render_errors: errors
}];

