/**
 * Converts input_json to tabular format for Google Sheets
 * Handles objects, arrays, and nested structures
 */

const prevData = $('INP_ValidateAndRoute').first().json;
const inputJson = prevData.input_json || {};
const currentData = $input.first().json;

const spreadsheetId = currentData.spreadsheetId || "";
const errors = [];

const rows = [];

try {
  // Check if input_json is already array of objects (table format)
  if (Array.isArray(inputJson)) {
    // Extract headers from first object
    if (inputJson.length > 0 && typeof inputJson[0] === "object") {
      const headers = Object.keys(inputJson[0]);
      rows.push(headers);

      // Add data rows
      inputJson.forEach(item => {
        const row = headers.map(h => item[h] || "");
        rows.push(row);
      });
    }
  } else if (typeof inputJson === "object") {
    // Convert object to key-value pairs
    rows.push(["Key", "Value"]);

    for (const [key, value] of Object.entries(inputJson)) {
      if (Array.isArray(value)) {
        rows.push([key, JSON.stringify(value)]);
      } else if (typeof value === "object" && value !== null) {
        rows.push([key, JSON.stringify(value, null, 2)]);
      } else {
        rows.push([key, String(value)]);
      }
    }
  }
} catch (e) {
  errors.push({
    stage: "render",
    message: `Sheet generation error: ${e.message}`
  });
}

// Convert rows to individual items for Google Sheets append
const items = rows.map((row, idx) => {
  const obj = {};
  row.forEach((cell, colIdx) => {
    obj[`col${colIdx}`] = cell;
  });
  return obj;
});

return items.length > 0 ? items : [{
  spreadsheet_id: spreadsheetId,
  error: "No data to insert",
  render_errors: errors
}];

const prevData = $('INP_ValidateAndRoute').first().json;
const currentData = $input.first().json;
const errors = [...(currentData.render_errors || [])];

let status = "ok";
let createdFileId = "";
let createdFileName = "";
let createdFileUrl = "";

// Detect file creation result based on document type
const docType = prevData.document_type;

if (currentData.error) {
  errors.push({
    stage: "create",
    message: currentData.error.message || "File creation failed"
  });
  status = "error";
} else {
  // Extract file info based on type
  if (docType === "google_doc") {
    createdFileId = currentData.documentId || currentData.id || "";
    createdFileUrl = `https://docs.google.com/document/d/${createdFileId}`;
  } else if (docType === "google_slides") {
    createdFileId = currentData.presentationId || currentData.presentation_id || currentData.id || "";
    createdFileUrl = `https://docs.google.com/presentation/d/${createdFileId}`;
  } else if (docType === "google_sheet") {
    createdFileId = currentData.spreadsheetId || currentData.id || "";
    createdFileUrl = `https://docs.google.com/spreadsheets/d/${createdFileId}`;
  }

  // Check if we got a file ID
  if (!createdFileId) {
    errors.push({
      stage: "create",
      message: "File created but could not extract file ID"
    });
    status = "partial";
  }

  createdFileName = currentData.title || currentData.name || 
                    `${docType}_${prevData.timestamp.split('T')[0]}`;
}

return [{
  status: status,
  mode: "CREATE_FILE",
  data: {
    google_drive_folder_id: prevData.google_drive_folder_id,
    document_type: docType,
    reference_template_url: prevData.reference_template_url,
    created_file_id: createdFileId,
    created_file_url: createdFileUrl,
    created_file_name: createdFileName
  },
  errors: errors
}];

